From 0f1ca403d5d02a5e2f728a110b99a1f06eb81aff Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:24:49 +0100
Subject: [PATCH] plasmaquick: open panel context menus outside auto-hide
 panels

Context menus of panels were only kept inside the screen's available
area, which excludes always-visible panels but not auto-hide ones, so
the menu covered the panel; now the menu is also moved past the panel.

BUG: 510908
---
 src/plasmaquick/plasmoid/containmentitem.cpp | 19 +++++++++++++++++++
 1 file changed, 19 insertions(+)

diff --git a/src/plasmaquick/plasmoid/containmentitem.cpp b/src/plasmaquick/plasmoid/containmentitem.cpp
index d8f65fc21..8239be12f 100644
--- a/src/plasmaquick/plasmoid/containmentitem.cpp
+++ b/src/plasmaquick/plasmoid/containmentitem.cpp
@@ -874,6 +874,25 @@ void ContainmentItem::mousePressEvent(QMouseEvent *event)
             pos = QPoint(qBound(geo.left(), pos.x(), geo.right() + 1 - m_contextMenu->width()),
                          qBound(geo.top(), pos.y(), geo.bottom() + 1 - m_contextMenu->height()));
         }
+
+        // Auto-hide and similar panels don't reserve screen space, so move the menu out of the panel explicitly
+        const QRect panelRect = mapRectToScene(boundingRect()).toAlignedRect().translated(window()->position());
+        switch (m_containment->location()) {
+        case Plasma::Types::LeftEdge:
+            pos.setX(std::max(pos.x(), panelRect.right() + 1));
+            break;
+        case Plasma::Types::RightEdge:
+            pos.setX(std::min(pos.x(), panelRect.left() - m_contextMenu->width()));
+            break;
+        case Plasma::Types::TopEdge:
+            pos.setY(std::max(pos.y(), panelRect.bottom() + 1));
+            break;
+        case Plasma::Types::BottomEdge:
+            pos.setY(std::min(pos.y(), panelRect.top() - m_contextMenu->height()));
+            break;
+        default:
+            break;
+        }
     }

     if (m_contextMenu->isEmpty()) {
-- 
